-- =============================================================================
-- MedTwin AI — Real-World Medical & Healthcare Digital Twin & AI Safety Platform
-- Relational schema (MySQL 8.4)
--
-- This file is the SOURCE OF TRUTH for the schema. Django models are declared
-- with `managed = False` and mirror these tables exactly.
--
--   mysql -u root medtwin < db/schema.sql
--
-- Design notes:
--   * Every table uses a VARCHAR(36) surrogate key generated by the application
--     so records can be created without an insert round-trip.
--   * Provenance is mandatory: health data always records its source_type and,
--     where relevant, the source document and author (PRD §9.3).
--   * Nothing medical is stored in a single free-text blob when a structured,
--     access-controlled model is available (PRD §21).
-- =============================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- Identity and access
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id             VARCHAR(36) NOT NULL,
  name           VARCHAR(120) NOT NULL,
  email          VARCHAR(190) NOT NULL,
  password_hash  VARCHAR(255) NOT NULL,
  role           ENUM('PATIENT','DOCTOR','ADMIN') NOT NULL DEFAULT 'PATIENT',
  phone          VARCHAR(40) NULL,
  avatar_color   VARCHAR(20) NOT NULL DEFAULT '#2563eb',
  language       ENUM('en','zh') NOT NULL DEFAULT 'en',
  is_active      TINYINT(1) NOT NULL DEFAULT 1,
  is_verified    TINYINT(1) NOT NULL DEFAULT 0,
  last_login_at  DATETIME NULL,
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email),
  KEY ix_users_role (role)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS roles (
  id           VARCHAR(36) NOT NULL,
  code         VARCHAR(40) NOT NULL,
  name         VARCHAR(80) NOT NULL,
  description  VARCHAR(255) NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_roles_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Permission mapping. `users.role` is the primary role; this table carries any
-- additional capabilities granted to an account (PRD §21 `user_roles`).
CREATE TABLE IF NOT EXISTS user_roles (
  id          VARCHAR(36) NOT NULL,
  user_id     VARCHAR(36) NOT NULL,
  role_id     VARCHAR(36) NOT NULL,
  granted_by  VARCHAR(36) NULL,
  granted_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_user_roles (user_id, role_id),
  CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id          VARCHAR(36) NOT NULL,
  user_id     VARCHAR(36) NOT NULL,
  token_hash  VARCHAR(128) NOT NULL,
  expires_at  DATETIME NOT NULL,
  used_at     DATETIME NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reset_token (token_hash),
  KEY ix_reset_user (user_id),
  CONSTRAINT fk_reset_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS patient_profiles (
  id                VARCHAR(36) NOT NULL,
  user_id           VARCHAR(36) NOT NULL,
  date_of_birth     DATE NULL,
  gender            ENUM('FEMALE','MALE','NON_BINARY','UNDISCLOSED') NOT NULL DEFAULT 'UNDISCLOSED',
  blood_type        VARCHAR(8) NULL,
  height_cm         DECIMAL(5,2) NULL,
  weight_kg         DECIMAL(5,2) NULL,
  city              VARCHAR(80) NULL,
  emergency_contact VARCHAR(120) NULL,
  summary           TEXT NULL,
  created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_patient_profile (user_id),
  CONSTRAINT fk_patient_profile_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS doctor_profiles (
  id                  VARCHAR(36) NOT NULL,
  user_id             VARCHAR(36) NOT NULL,
  specialization      VARCHAR(120) NULL,
  license_number      VARCHAR(60) NULL,
  hospital            VARCHAR(160) NULL,
  department          VARCHAR(120) NULL,
  bio                 TEXT NULL,
  verification_status ENUM('PENDING','VERIFIED','REJECTED') NOT NULL DEFAULT 'PENDING',
  verified_at         DATETIME NULL,
  created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_doctor_profile (user_id),
  CONSTRAINT fk_doctor_profile_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Consent and professional access (PRD §8.3)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS consent_grants (
  id          VARCHAR(36) NOT NULL,
  patient_id  VARCHAR(36) NOT NULL,
  doctor_id   VARCHAR(36) NOT NULL,
  scope       JSON NOT NULL,
  purpose     VARCHAR(255) NULL,
  status      ENUM('PENDING','ACTIVE','REJECTED','REVOKED','EXPIRED') NOT NULL DEFAULT 'PENDING',
  granted_at  DATETIME NULL,
  expires_at  DATETIME NULL,
  revoked_at  DATETIME NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_consent_patient (patient_id, status),
  KEY ix_consent_doctor (doctor_id, status),
  CONSTRAINT fk_consent_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_consent_doctor  FOREIGN KEY (doctor_id)  REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Digital Twin health data (PRD §9)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS health_records (
  id                  VARCHAR(36) NOT NULL,
  patient_id          VARCHAR(36) NOT NULL,
  category            ENUM('CONDITION','ALLERGY','MEDICATION','LAB_RESULT','PROCEDURE','IMMUNIZATION','NOTE','FAMILY_HISTORY','VITAL') NOT NULL,
  title               VARCHAR(200) NOT NULL,
  summary             TEXT NULL,
  payload             JSON NULL,
  source_type         ENUM('USER','CLINICIAN','EXTRACTED','AI_GENERATED','DEVICE') NOT NULL DEFAULT 'USER',
  verification_status ENUM('UNVERIFIED','USER_CONFIRMED','CLINICIAN_CONFIRMED','EXTRACTED_REVIEWED') NOT NULL DEFAULT 'UNVERIFIED',
  source_document_id  VARCHAR(36) NULL,
  author_id           VARCHAR(36) NULL,
  recorded_at         DATETIME NULL,
  created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_record_patient (patient_id, category),
  KEY ix_record_recorded (patient_id, recorded_at),
  CONSTRAINT fk_record_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_record_author  FOREIGN KEY (author_id)  REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS observations (
  id                VARCHAR(36) NOT NULL,
  patient_id        VARCHAR(36) NOT NULL,
  code              VARCHAR(40) NULL,
  label             VARCHAR(120) NOT NULL,
  value_numeric     DECIMAL(12,4) NULL,
  value_text        VARCHAR(255) NULL,
  unit              VARCHAR(30) NULL,
  reference_range   VARCHAR(60) NULL,
  flag              ENUM('NORMAL','LOW','HIGH','CRITICAL','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  observed_at       DATETIME NOT NULL,
  source_type       ENUM('USER','CLINICIAN','EXTRACTED','AI_GENERATED','DEVICE') NOT NULL DEFAULT 'USER',
  source_document_id VARCHAR(36) NULL,
  created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_obs_patient (patient_id, observed_at),
  KEY ix_obs_label (patient_id, label),
  CONSTRAINT fk_obs_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS allergies (
  id           VARCHAR(36) NOT NULL,
  patient_id   VARCHAR(36) NOT NULL,
  substance    VARCHAR(120) NOT NULL,
  reaction     VARCHAR(255) NULL,
  severity     ENUM('MILD','MODERATE','SEVERE','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  status       ENUM('ACTIVE','RESOLVED','UNKNOWN') NOT NULL DEFAULT 'ACTIVE',
  source_type  ENUM('USER','CLINICIAN','EXTRACTED','AI_GENERATED','DEVICE') NOT NULL DEFAULT 'USER',
  reviewed_at  DATETIME NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_allergy_patient (patient_id, status),
  CONSTRAINT fk_allergy_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS medications (
  id          VARCHAR(36) NOT NULL,
  patient_id  VARCHAR(36) NOT NULL,
  name        VARCHAR(160) NOT NULL,
  dose        VARCHAR(80) NULL,
  frequency   VARCHAR(80) NULL,
  route       VARCHAR(40) NULL,
  status      ENUM('ACTIVE','STOPPED','UNKNOWN') NOT NULL DEFAULT 'ACTIVE',
  started_at  DATE NULL,
  ended_at    DATE NULL,
  source_type ENUM('USER','CLINICIAN','EXTRACTED','AI_GENERATED','DEVICE') NOT NULL DEFAULT 'USER',
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_med_patient (patient_id, status),
  CONSTRAINT fk_med_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Documents and extraction (PRD §10)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS documents (
  id                VARCHAR(36) NOT NULL,
  owner_id          VARCHAR(36) NOT NULL,
  patient_id        VARCHAR(36) NOT NULL,
  name              VARCHAR(255) NOT NULL,
  mime_type         VARCHAR(120) NOT NULL,
  size_bytes        INT UNSIGNED NOT NULL DEFAULT 0,
  storage_path      VARCHAR(400) NOT NULL,
  sha256            VARCHAR(64) NULL,
  category          VARCHAR(40) NOT NULL DEFAULT 'OTHER',
  processing_status ENUM('UPLOADED','PROCESSING','PROCESSED','FAILED') NOT NULL DEFAULT 'UPLOADED',
  processing_error  VARCHAR(255) NULL,
  extracted_text    LONGTEXT NULL,
  page_count        INT UNSIGNED NULL,
  uploaded_by       VARCHAR(36) NULL,
  created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  processed_at      DATETIME NULL,
  PRIMARY KEY (id),
  KEY ix_doc_patient (patient_id, created_at),
  CONSTRAINT fk_doc_owner   FOREIGN KEY (owner_id)   REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_doc_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS document_extractions (
  id             VARCHAR(36) NOT NULL,
  document_id    VARCHAR(36) NOT NULL,
  field_name     VARCHAR(80) NOT NULL,
  label          VARCHAR(120) NULL,
  value          VARCHAR(255) NULL,
  confidence     DECIMAL(4,3) NULL,
  review_status  ENUM('PENDING','CONFIRMED','CORRECTED','REJECTED') NOT NULL DEFAULT 'PENDING',
  evidence       VARCHAR(400) NULL,
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_extraction_doc (document_id),
  CONSTRAINT fk_extraction_doc FOREIGN KEY (document_id) REFERENCES documents (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS timeline_events (
  id           VARCHAR(36) NOT NULL,
  patient_id   VARCHAR(36) NOT NULL,
  event_type   VARCHAR(40) NOT NULL,
  title        VARCHAR(200) NOT NULL,
  description  TEXT NULL,
  occurred_at  DATETIME NOT NULL,
  source_type  ENUM('USER','CLINICIAN','EXTRACTED','AI_GENERATED','DEVICE') NOT NULL DEFAULT 'USER',
  source_id    VARCHAR(36) NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_timeline_patient (patient_id, occurred_at),
  CONSTRAINT fk_timeline_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Conversations, appointments, notifications (PRD §18)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS conversations (
  id          VARCHAR(36) NOT NULL,
  patient_id  VARCHAR(36) NOT NULL,
  doctor_id   VARCHAR(36) NULL,
  title       VARCHAR(160) NULL,
  channel     ENUM('PATIENT_AI','PATIENT_DOCTOR') NOT NULL DEFAULT 'PATIENT_DOCTOR',
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_conv_patient (patient_id, channel),
  KEY ix_conv_doctor (doctor_id),
  CONSTRAINT fk_conv_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_conv_doctor  FOREIGN KEY (doctor_id)  REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS messages (
  id              VARCHAR(36) NOT NULL,
  conversation_id VARCHAR(36) NOT NULL,
  sender_id       VARCHAR(36) NULL,
  role            ENUM('USER','AI','DOCTOR','SYSTEM') NOT NULL DEFAULT 'USER',
  body            TEXT NOT NULL,
  attachments     JSON NULL,
  metadata        JSON NULL,
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  read_at         DATETIME NULL,
  PRIMARY KEY (id),
  KEY ix_msg_conversation (conversation_id, created_at),
  CONSTRAINT fk_msg_conversation FOREIGN KEY (conversation_id) REFERENCES conversations (id) ON DELETE CASCADE,
  CONSTRAINT fk_msg_sender       FOREIGN KEY (sender_id)       REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS appointments (
  id           VARCHAR(36) NOT NULL,
  patient_id   VARCHAR(36) NOT NULL,
  doctor_id    VARCHAR(36) NULL,
  scheduled_at DATETIME NOT NULL,
  duration_min INT NOT NULL DEFAULT 30,
  timezone     VARCHAR(60) NOT NULL DEFAULT 'UTC',
  reason       VARCHAR(255) NULL,
  status       ENUM('REQUESTED','CONFIRMED','DECLINED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'REQUESTED',
  notes        TEXT NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_appt_patient (patient_id, scheduled_at),
  KEY ix_appt_doctor (doctor_id, scheduled_at),
  CONSTRAINT fk_appt_patient FOREIGN KEY (patient_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_appt_doctor  FOREIGN KEY (doctor_id)  REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notifications (
  id          VARCHAR(36) NOT NULL,
  user_id     VARCHAR(36) NOT NULL,
  type        VARCHAR(40) NOT NULL,
  title       VARCHAR(200) NOT NULL,
  body        TEXT NULL,
  link        VARCHAR(200) NULL,
  is_read     TINYINT(1) NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_notif_user (user_id, is_read, created_at),
  CONSTRAINT fk_notif_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- AI: interactions, knowledge base, recommendations (PRD §12–§17)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_sources (
  id              VARCHAR(36) NOT NULL,
  title           VARCHAR(255) NOT NULL,
  publisher       VARCHAR(160) NULL,
  version         VARCHAR(60) NULL,
  source_url      VARCHAR(500) NULL,
  category        VARCHAR(60) NULL,
  license_status  ENUM('OPEN','LICENSED','RESTRICTED','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  review_status   ENUM('PENDING','APPROVED','REJECTED','EXPIRED') NOT NULL DEFAULT 'PENDING',
  ingested_at     DATETIME NULL,
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_source_review (review_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS knowledge_chunks (
  id                    VARCHAR(36) NOT NULL,
  source_id             VARCHAR(36) NOT NULL,
  chunk_index           INT NOT NULL DEFAULT 0,
  title                 VARCHAR(255) NULL,
  text                  TEXT NOT NULL,
  tokens                INT NOT NULL DEFAULT 0,
  access_classification ENUM('PUBLIC','CLINICAL','RESTRICTED') NOT NULL DEFAULT 'PUBLIC',
  created_at            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_chunk_source (source_id, chunk_index),
  FULLTEXT KEY ft_chunk_text (text),
  CONSTRAINT fk_chunk_source FOREIGN KEY (source_id) REFERENCES knowledge_sources (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ai_interactions (
  id              VARCHAR(36) NOT NULL,
  user_id         VARCHAR(36) NULL,
  conversation_id VARCHAR(36) NULL,
  request_type    VARCHAR(40) NOT NULL DEFAULT 'CHAT',
  prompt          TEXT NOT NULL,
  answer          TEXT NULL,
  intent          VARCHAR(60) NULL,
  risk_category   ENUM('NORMAL','SENSITIVE','URGENT','OUT_OF_SCOPE') NOT NULL DEFAULT 'NORMAL',
  model_name      VARCHAR(80) NULL,
  model_version   VARCHAR(40) NULL,
  sources         JSON NULL,
  safety          JSON NULL,
  trust_score     DECIMAL(5,2) NULL,
  latency_ms      INT NULL,
  trace_id        VARCHAR(40) NULL,
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_ai_user (user_id, created_at),
  KEY ix_ai_conversation (conversation_id, created_at),
  CONSTRAINT fk_ai_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS recommendations (
  id            VARCHAR(36) NOT NULL,
  user_id       VARCHAR(36) NOT NULL,
  type          ENUM('EDUCATION','QUESTION_TO_ASK','FOLLOW_UP','NEXT_STEP') NOT NULL DEFAULT 'EDUCATION',
  title         VARCHAR(200) NOT NULL,
  body          TEXT NULL,
  basis         JSON NULL,
  status        ENUM('ACTIVE','DISMISSED','ACCEPTED') NOT NULL DEFAULT 'ACTIVE',
  responded_at  DATETIME NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_rec_user (user_id, status),
  CONSTRAINT fk_rec_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Trust & Safety / model governance (PRD §15, §19.3)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS model_versions (
  id          VARCHAR(36) NOT NULL,
  name        VARCHAR(80) NOT NULL,
  version     VARCHAR(40) NOT NULL,
  provider    VARCHAR(80) NULL,
  kind        ENUM('LLM','EMBEDDING','SAFETY','DETECTOR') NOT NULL DEFAULT 'LLM',
  config      JSON NULL,
  is_active   TINYINT(1) NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_model_kind (kind, is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS evaluation_runs (
  id               VARCHAR(36) NOT NULL,
  model_version_id VARCHAR(36) NULL,
  dataset_version  VARCHAR(40) NULL,
  metrics          JSON NULL,
  status           ENUM('PENDING','RUNNING','COMPLETED','FAILED') NOT NULL DEFAULT 'PENDING',
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT fk_eval_model FOREIGN KEY (model_version_id) REFERENCES model_versions (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS deepfake_analyses (
  id             VARCHAR(36) NOT NULL,
  owner_id       VARCHAR(36) NULL,
  file_name      VARCHAR(255) NULL,
  mime_type      VARCHAR(120) NULL,
  storage_path   VARCHAR(400) NULL,
  modality       ENUM('IMAGE','AUDIO','VIDEO','DOCUMENT') NOT NULL DEFAULT 'IMAGE',
  model_version  VARCHAR(40) NULL,
  result         JSON NULL,
  risk_level     ENUM('LOW','MEDIUM','HIGH','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  uncertainty    DECIMAL(4,3) NULL,
  limitations    TEXT NULL,
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_deepfake_owner (owner_id, created_at),
  CONSTRAINT fk_deepfake_owner FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Audit and operations (PRD §8.2, §19.3)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit_logs (
  id            VARCHAR(36) NOT NULL,
  actor_id      VARCHAR(36) NULL,
  actor_email   VARCHAR(190) NULL,
  action        VARCHAR(60) NOT NULL,
  resource_type VARCHAR(60) NULL,
  resource_id   VARCHAR(36) NULL,
  outcome       ENUM('SUCCESS','DENIED','ERROR') NOT NULL DEFAULT 'SUCCESS',
  ip_address    VARCHAR(60) NULL,
  user_agent    VARCHAR(255) NULL,
  trace_id      VARCHAR(40) NULL,
  metadata      JSON NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_audit_created (created_at),
  KEY ix_audit_actor (actor_id, created_at),
  KEY ix_audit_action (action, created_at),
  KEY ix_audit_resource (resource_type, resource_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS feature_flags (
  id           VARCHAR(36) NOT NULL,
  flag_key     VARCHAR(60) NOT NULL,
  label        VARCHAR(160) NULL,
  description  VARCHAR(400) NULL,
  is_enabled   TINYINT(1) NOT NULL DEFAULT 0,
  status       ENUM('PLANNED','IN_DEVELOPMENT','IMPLEMENTED','EVALUATED','RELEASED') NOT NULL DEFAULT 'PLANNED',
  updated_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_flag_key (flag_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Django framework tables (session store + migration bookkeeping)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS django_session (
  session_key  VARCHAR(40) NOT NULL,
  session_data LONGTEXT NOT NULL,
  expire_date  DATETIME(6) NOT NULL,
  PRIMARY KEY (session_key),
  KEY ix_django_session_expire (expire_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id      BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
  app     VARCHAR(255) NOT NULL,
  name    VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
